function getAuthByHost(input, host) {
    if (!input || !Array.isArray(input.config)) {
        return null;
    }

    for (const item of input.config) {
        if (Array.isArray(item.host) && item.host.includes(host)) {
            return item.auth;
        }
    }

    return null;
};

